(7002021, 1057052, 65234, '<td valign="top">Never thought I''d say this (I love wildlife shots!) but for this challenge I think I''d like it better without the waterfowl.  There are some very cool patterns in the water.</td>', 'Never thought I''d say this (I love wildlife shots!) but for this challenge I think I''d like it better without the waterfowl.  There are some very cool patterns in the water.', '2013-03-17 21:48:22.000000', NULL, 1),
(7002022, 1057348, 63218, '<td valign="top">Perfectly done! The colors &amp; tones are easy on the eye, &amp; the texture detail is interesting. Good work.</td>', 'Perfectly done! The colors & tones are easy on the eye, & the texture detail is interesting. Good work.', '2013-03-17 21:50:04.000000', NULL, 1),
(7002023, 1057623, 65234, '<td valign="top">Could just be my monitor, but the background is so bright and saturated I''m having trouble appreciating the flowers.</td>', 'Could just be my monitor, but the background is so bright and saturated I''m having trouble appreciating the flowers.', '2013-03-17 21:50:15.000000', NULL, 1),
(7002025, 1057349, 63218, '<td valign="top">Pretty little crocus in the spring sunshine.</td>', 'Pretty little crocus in the spring sunshine.', '2013-03-17 21:50:46.000000', NULL, 1),
(7002027, 1057408, 65234, '<td valign="top">Hydrangea!  I''ve come to really love them, especially in winter when the flowers are translucent and delicate and glow in the afternoon sun.  They hang on tenaciously till the next generation surplants them.<br/> <br/>Nicely composed.</td>', 'Hydrangea!  I''ve come to really love them, especially in winter when the flowers are translucent and delicate and glow in the afternoon sun.  They hang on tenaciously till the next generation surplants them. Nicely composed.', '2013-03-17 21:52:05.000000', NULL, 1),
(7002029, 1057417, 63218, '<td valign="top">I love this color.</td>', 'I love this color.', '2013-03-17 21:53:26.000000', NULL, 1),
(7002030, 1057190, 63218, '<td valign="top">Ah, sunflower. Black BG is unusual,but good.</td>', 'Ah, sunflower. Black BG is unusual,but good.', '2013-03-17 21:54:01.000000', NULL, 1),
(7002031, 1057388, 65234, '<td valign="top">I don''t think of mice as having anything to do with serenity!  They''re such busy little critters, and so many other things leap into action to catch or flee from them as soon as they see one.  But he is beautiful, in his own mousy way.</td>', 'I don''t think of mice as having anything to do with serenity!  They''re such busy little critters, and so many other things leap into action to catch or flee from them as soon as they see one.  But he is beautiful, in his own mousy way.', '2013-03-17 21:54:34.000000', NULL, 1),
(7002032, 1057113, 63218, '<td valign="top">This is awesome.</td>', 'This is awesome.', '2013-03-17 21:55:11.000000', NULL, 1),
(7002033, 1057523, 65234, '<td valign="top">Love the shapes and the differing materials making them.  Well seen and captured.</td>', 'Love the shapes and the differing materials making them.  Well seen and captured.', '2013-03-17 21:55:41.000000', NULL, 1),
